/**
 * CommentThread.Comment: one comment: its author, time, body, labels, actions and replies.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/comment-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, useContext, type JSX } from 'solid-js'

import {
  claimSlot,
  createDerived,
  ownerContext,
  resolveSlot,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/comment-thread.module.css'
import type { CommentThreadOwner } from './CommentThread'

export interface CommentThreadCommentProps {
  /**
   * The app's controls for this comment: ghost neutral sm Buttons, or a Menu.
   */
  actions?: JSX.Element
  /**
   * The author's name, drawn first. With the time it names the comment's article.
   */
  author: string
  /**
   * An Avatar with the author's name, drawn in a column one md Avatar wide.
   */
  avatar?: JSX.Element
  /**
   * The body: Text, Markdown or the app's own nodes, and a row of AttachmentChips.
   */
  children?: JSX.Element
  /**
   * The comment was changed after it was posted: the head says so after the time.
   */
  edited?: boolean
  /**
   * Labels after the head's words: Badges such as "Internal note" or "Resolved".
   */
  meta?: JSX.Element
  /**
   * The replies, as `CommentThread.Comment`s, drawn indented under the comment.
   */
  replies?: JSX.Element
  /**
   * When it was written: a RelativeTime, or text the app has formatted.
   */
  time?: JSX.Element
}

/** CommentThread.Comment: one comment: its author, time, body, labels, actions and replies. */
export default function CommentThreadComment(given: CommentThreadCommentProps): JSX.Element {
  const props = mergeProps(
    { edited: false } as Defaults<CommentThreadCommentProps, 'edited'>,
    claimSlot(given),
  )
  const owner =
    useContext(ownerContext<CommentThreadOwner>('CommentThread')) ?? ({} as CommentThreadOwner)
  return scope(() => {
    const uid = createUniqueId()
    const actionsSlot = resolveSlot(() => props.actions)
    const avatarSlot = resolveSlot(() => props.avatar)
    const metaSlot = resolveSlot(() => props.meta)
    const repliesSlot = resolveSlot(() => props.replies)
    const timeSlot = resolveSlot(() => props.time)
    const words = createDerived(() => owner.messages ?? { edited: 'Edited', replies: 'Replies' })
    const authorId = createDerived(() => `${uid}-author`)
    const timeId = createDerived(() => `${uid}-time`)
    return (
      <li class={styles.comment}>
        <article
          class={styles.entry}
          aria-labelledby={timeSlot.filled() ? `${authorId.value} ${timeId.value}` : authorId.value}
        >
          {avatarSlot.filled() ? <span class={styles.mark}>{avatarSlot()}</span> : null}
          <div class={styles.body}>
            <div class={styles.head}>
              <span class={styles.author} id={authorId.value}>
                {props.author}
              </span>
              {timeSlot.filled() ? (
                <span class={styles.time} id={timeId.value}>
                  {timeSlot()}
                </span>
              ) : null}
              {props.edited ? <span class={styles.edited}>{words.value.edited}</span> : null}
              {metaSlot.filled() ? <span class={styles.meta}>{metaSlot()}</span> : null}
            </div>
            <div class={styles.content}>{props.children}</div>
            {actionsSlot.filled() ? <div class={styles.actions}>{actionsSlot()}</div> : null}
          </div>
        </article>
        {repliesSlot.filled() ? (
          <ol class={styles.replies} role="list" aria-label={words.value.replies}>
            {repliesSlot()}
          </ol>
        ) : null}
      </li>
    )
  })
}
